import flask
from flask import request, jsonify
import subprocess
import os
import re
import tempfile
import shlex

app = flask.Flask(__name__)

# Configuration
REPORT_DIR = os.environ.get('REPORT_DIR', '/var/reports')
ALLOWED_FORMATS = ['pdf', 'csv', 'xlsx']
MAX_TITLE_LEN = 200

def sanitize_filename(name):
    """Remove path traversal attempts but allow alphanumeric, dash, underscore"""
    cleaned = re.sub(r'[^a-zA-Z0-9_\-]', '_', name)
    return cleaned[:64]

def validate_format(fmt):
    if fmt not in ALLOWED_FORMATS:
        raise ValueError(f"Invalid format: {fmt}")
    return fmt

@app.route('/api/v1/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report using the system's wkhtmltopdf or libreoffice converter.
    Accepts JSON body with: title, template, format, filters
    """
    data = request.get_json()
    if not data:
        return jsonify({"error": "JSON body required"}), 400

    title = data.get('title', 'Untitled Report')
    template = data.get('template', 'default')
    fmt = data.get('format', 'pdf')
    date_range = data.get('date_range', 'last_30d')
    custom_header = data.get('custom_header', '')

    # Validate inputs
    if len(title) > MAX_TITLE_LEN:
        return jsonify({"error": "Title too long"}), 400

    try:
        fmt = validate_format(fmt)
    except ValueError as e:
        return jsonify({"error": str(e)}), 400

    safe_title = sanitize_filename(title)
    template_path = f"/opt/templates/{sanitize_filename(template)}.html"

    if not os.path.exists(template_path):
        return jsonify({"error": "Template not found"}), 404

    # Build output path
    output_file = os.path.join(REPORT_DIR, f"{safe_title}_{date_range}.{fmt}")

    # Construct the conversion command
    # custom_header is injected into wkhtmltopdf's --header-center option
    cmd = f'wkhtmltopdf --header-center "{custom_header}" --title "{title}" {template_path} {output_file}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=REPORT_DIR
        )
        if result.returncode != 0:
            app.logger.error(f"wkhtmltopdf failed: {result.stderr.decode()}")
            return jsonify({"error": "Report generation failed"}), 500
    except subprocess.TimeoutExpired:
        return jsonify({"error": "Report generation timed out"}), 504

    return jsonify({
        "status": "success",
        "output": output_file,
        "size": os.path.getsize(output_file)
    })

@app.route('/api/v1/reports/list', methods=['GET'])
def list_reports():
    """List generated reports"""
    try:
        files = os.listdir(REPORT_DIR)
        reports = [f for f in files if any(f.endswith(ext) for ext in ALLOWED_FORMATS)]
        return jsonify({"reports": reports})
    except OSError:
        return jsonify({"reports": []})

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.4.1"})

if __name__ == '__main__':
    os.makedirs(REPORT_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
